insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'gk_science_v1'
from (values
('112.2.b.6',2,'Which word tells about the TEXTURE of a cotton ball?','["soft", "heavy", "cold", "loud"]'::jsonb,0,'Texture is how something feels. A cotton ball feels soft.','original'),
('112.2.b.6',2,'Which material is a brick for building a wall made of?','["glass", "baked clay", "cloth", "paper"]'::jsonb,1,'Material is what an object is made of. A brick is made of baked clay.','original'),
('112.2.b.6',3,'You sort blocks into two groups: RED and BLUE. What property did you use?','["shape", "material", "color", "texture"]'::jsonb,2,'Sorting into red and blue groups uses color.','original'),
('112.2.b.6',2,'Which object is made of metal?','["a paper cup", "a wool sock", "a wooden block", "a spoon"]'::jsonb,3,'A spoon is usually made of metal. The others are paper, wool, and wood.','original'),
('112.2.b.6',3,'Which two objects have the same SHAPE?','["a ball and an orange", "a box and an orange", "a pencil and a ball", "a ball and a book"]'::jsonb,0,'A ball and an orange are both round like a sphere.','original'),
('112.2.b.6',3,'A sandpaper sheet feels rough. A glass window feels smooth. What property is different?','["shape", "texture", "color", "size"]'::jsonb,1,'Rough and smooth tell how things feel, which is texture.','original'),
('112.2.b.6',4,'Which group could hold ONLY things made of wood?','["a spoon, a coin, a key", "a sock, a hat, a scarf", "a pencil, a chair, a block", "a bottle, a cup, a bowl made of plastic"]'::jsonb,2,'A pencil, a chair, and a block can all be made of wood.','original'),
('112.2.b.7',2,'Which object will a magnet pull toward it?','["a wooden spoon", "a paper cup", "a rubber ball", "a metal paper clip"]'::jsonb,3,'Magnets pull some metals, like iron. A paper clip is made of steel.','original'),
('112.2.b.7',2,'Which object will a magnet NOT pick up?','["a plastic toy", "a steel paper clip", "a steel nail", "an iron key"]'::jsonb,0,'Magnets do not pull plastic.','original'),
('112.2.b.7',3,'A magnet moves a toy car closer to it. What did the magnet do?','["melted the car", "pulled the car", "pushed the car", "painted the car"]'::jsonb,1,'Moving the car closer means the magnet pulled it.','original'),
('112.2.b.7',3,'Two magnets are put together and move AWAY from each other. What happened?','["they broke", "they pulled each other", "they pushed each other", "they got warm"]'::jsonb,2,'Magnets can push each other away.','original'),
('112.2.b.7',2,'A magnet can make some things move without touching them. What does a magnet do?','["makes sound", "grows plants", "makes light", "pushes or pulls"]'::jsonb,3,'A magnet pushes or pulls some objects.','original'),
('112.2.b.7',3,'You predict a magnet will pick up a coin made of wood. Is it a good prediction?','["no, wood is not pulled by a magnet", "yes, magnets pick up all things", "no, coins are too small", "yes, wood is metal"]'::jsonb,0,'Magnets do not pull wood.','original'),
('112.2.b.7',4,'Which tool could a magnet help you use to pick up pins spilled on the floor?','["a wooden ruler", "a magnet on a stick", "a plastic comb", "a paper towel tube"]'::jsonb,1,'Steel pins are pulled to a magnet.','original'),
('112.2.b.8.A',2,'What do you need in order to see objects?','["water", "wind", "light", "silence"]'::jsonb,2,'Objects can only be seen when there is light.','original'),
('112.2.b.8.A',2,'A closet has no light and the door is shut. What can you see inside?','["only big things", "everything clearly", "only red things", "nothing"]'::jsonb,3,'Without a light source, objects cannot be seen.','original'),
('112.2.b.8.A',3,'Which is a source of light?','["the Sun", "the Moon", "a mirror", "a white wall"]'::jsonb,0,'The Sun makes its own light. The Moon and a mirror only reflect light.','original'),
('112.2.b.8.A',3,'Which room is the BRIGHTEST?','["a room with the curtains closed and no lights", "a room with the lamp on and the window open", "a room with only a small night-light", "a room with the lights off"]'::jsonb,1,'More light makes things look brighter.','original'),
('112.2.b.8.A',3,'It is dim in a room. What can you do to see a book better?','["turn off the light", "cover the window", "turn on a lamp", "close your eyes"]'::jsonb,2,'A lamp adds light so the book is easier to see.','original'),
('112.2.b.8.A',2,'Which object makes its own light?','["a shoe", "a book", "a rock", "a flashlight"]'::jsonb,3,'A flashlight makes light. The others do not.','original'),
('112.2.b.8.A',4,'Two pictures are on a wall. One is in bright light and one is in dim light. Which is easier to see?','["the one in bright light", "neither one", "the one in dim light", "they look the same"]'::jsonb,0,'More light makes objects easier to see.','original'),
('112.2.b.8.B',2,'Light goes through a clear window. What does the window do to light?','["makes light heavier", "lets light pass through", "blocks all the light", "turns light into sound"]'::jsonb,1,'Clear glass lets light pass through.','original'),
('112.2.b.8.B',2,'What makes a shadow?','["something that is soft", "something that makes sound", "something that blocks light", "something that is cold"]'::jsonb,2,'A shadow forms when an object blocks light.','original'),
('112.2.b.8.B',3,'Which object makes the DARKEST shadow?','["a clear plastic bag", "a clear glass cup", "clear plastic wrap", "a wooden board"]'::jsonb,3,'A wooden board blocks light. Clear things let light through.','original'),
('112.2.b.8.B',3,'Where do you see your shadow on a sunny day?','["on the ground away from the Sun", "inside the Sun", "behind a clear window", "in the sky"]'::jsonb,0,'Your body blocks sunlight, so a shadow forms on the ground.','original'),
('112.2.b.8.B',3,'Which object lets MOST light pass through?','["a cardboard box", "a clear glass jar", "a metal pot", "a wooden door"]'::jsonb,1,'A clear glass jar lets light through.','original'),
('112.2.b.8.B',2,'A student holds a hand in front of a flashlight. What appears on the wall?','["a rainbow", "a sound", "a shadow", "a plant"]'::jsonb,2,'The hand blocks the light and makes a shadow.','original'),
('112.2.b.8.B',4,'Which object blocks light, so it makes a shadow?','["a clean glass window", "clear water in a glass", "clear plastic wrap", "a book"]'::jsonb,3,'A book blocks light. The other choices are clear.','original'),
('112.2.b.9.A',1,'When is the Sun seen in the sky?','["during the day", "only in winter", "never", "at night"]'::jsonb,0,'We see the Sun during the day.','original'),
('112.2.b.9.A',2,'What comes after day?','["summer", "night", "spring", "day again right away"]'::jsonb,1,'Night follows day.','original'),
('112.2.b.9.A',2,'Which is something you can see in the sky at night?','["a rainbow", "the Sun", "stars", "a sunrise"]'::jsonb,2,'Stars are seen at night. The Sun is seen during the day.','original'),
('112.2.b.9.A',2,'When do most people sleep?','["in the morning sun", "at noon when it is bright", "when the Sun is highest", "at night when it is dark"]'::jsonb,3,'Most people sleep at night when it is dark.','original'),
('112.2.b.9.A',3,'Is it warmer outside in the middle of a sunny day or in the middle of the night?','["in the middle of the day", "they are always the same", "in the middle of the night", "it is warmer at night in every season"]'::jsonb,0,'The Sun warms the Earth during the day.','original'),
('112.2.b.9.A',3,'The pattern of day and night happens over and over. Which comes first, then second?','["day, day, day", "day, then night, then day", "night, then night, then day", "night, night, night"]'::jsonb,1,'Day and night take turns in a repeating pattern.','original'),
('112.2.b.9.A',4,'A student sees the Sun coming up in the morning. What will happen later that day?','["the Sun will stay up all night", "the stars will come out first", "the Sun will go down and it will get dark", "the Moon will stay out all day"]'::jsonb,2,'After the Sun sets, it gets dark and night begins.','original'),
('112.2.b.9.B',2,'Which object in the sky gives us light and heat during the day?','["a cloud", "the Moon", "a star at night", "the Sun"]'::jsonb,3,'The Sun gives light and heat to Earth.','original'),
('112.2.b.9.B',2,'Which of these can you see in the sky during the day?','["clouds", "stars shining bright", "a dark sky", "a night-light"]'::jsonb,0,'Clouds are seen in the sky during the day.','original'),
('112.2.b.9.B',3,'Which sky object do people often see at night with a different shape on different nights?','["a rainbow", "the Moon", "the Sun", "a cloud"]'::jsonb,1,'The Moon looks different on different nights.','original'),
('112.2.b.9.B',3,'Which sky objects look like tiny dots of light at night?','["rainbows", "clouds", "stars", "birds"]'::jsonb,2,'Stars look like tiny dots of light at night.','original'),
('112.2.b.9.B',2,'Which sky object is white and fluffy?','["the Moon", "the Sun", "a star", "a cloud"]'::jsonb,3,'Many clouds look white and fluffy.','original'),
('112.2.b.9.B',3,'A student draws the sky at night. Which picture shows a night sky?','["the Moon and stars", "only a rainbow", "a bright blue sky with the Sun", "the Sun and a rainbow"]'::jsonb,0,'Moon and stars are seen at night.','original'),
('112.2.b.9.B',4,'Which sky object is closest to Earth?','["a faraway star", "the Moon", "the Sun", "a star"]'::jsonb,1,'The Moon is the closest object of these to Earth.','original'),
('112.2.b.10.A',2,'Which rock is the BIGGEST?','["a grain of sand", "a pebble you can hold", "a boulder as big as a car", "a small stone"]'::jsonb,2,'A boulder is the biggest of these rocks. A grain of sand is the smallest.','original'),
('112.2.b.10.A',2,'Which word describes the SHAPE of a rock that looks like a ball?','["long and thin", "flat", "square", "round"]'::jsonb,3,'A ball shape is round. It has no flat sides or corners.','original'),
('112.2.b.10.A',3,'Two rocks are the same size and shape. One is red and one is gray. What is different?','["color", "shape", "size", "weight"]'::jsonb,0,'The rocks match in size and shape. Only the color is different.','original'),
('112.2.b.10.A',2,'Which rock feels SMOOTH when you touch it?','["a rough rock with many bumps", "a river stone worn down by water", "a broken rock with jagged edges", "a rock with many sharp points"]'::jsonb,1,'Water wears rocks smooth over time. Sharp, bumpy, and jagged rocks feel rough.','original'),
('112.2.b.10.A',3,'A student sorts rocks into a SMOOTH group and a ROUGH group. Which rock goes in the SMOOTH group?','["a rock with pits and bumps", "a rock with sharp broken edges", "a rock with a shiny, polished surface", "a rock covered in tiny grains"]'::jsonb,2,'A shiny, polished rock feels smooth. The other three feel rough.','original'),
('112.2.b.10.A',2,'Which rock has a FLAT shape, like a pancake?','["a pointed cone", "a long stick", "a round ball", "a flat slab"]'::jsonb,3,'A slab is flat. A ball is round, and a cone and a stick are not flat.','original'),
('112.2.b.10.A',3,'Which list puts rocks in order from SMALLEST to BIGGEST?','["a grain of sand, a pebble, a boulder", "a boulder, a grain of sand, a pebble", "a boulder, a pebble, a grain of sand", "a pebble, a boulder, a grain of sand"]'::jsonb,0,'A grain of sand is the smallest, then a pebble, then a boulder.','original'),
('112.2.b.10.B',1,'Which is a kind of weather?','["round", "rainy", "loud", "soft"]'::jsonb,1,'Rainy tells what the weather is like.','original'),
('112.2.b.10.B',2,'Which season is usually the coldest?','["summer", "all seasons are the same", "winter", "spring"]'::jsonb,2,'Winter is usually the coldest season.','original'),
('112.2.b.10.B',2,'Which season usually has the hottest days?','["winter", "spring", "fall", "summer"]'::jsonb,3,'Summer usually has the hottest days.','original'),
('112.2.b.10.B',3,'Monday was sunny. Tuesday was rainy. What does this show?','["weather can change from day to day", "it is always sunny on Monday", "it only rains on Tuesday", "weather never changes"]'::jsonb,0,'Weather can be different from one day to the next.','original'),
('112.2.b.10.B',3,'Leaves change color and drop off many trees, and the days get cooler. Which season is it?','["spring", "fall", "winter", "summer"]'::jsonb,1,'Falling leaves and cooler days are signs of fall.','original'),
('112.2.b.10.B',2,'What should you wear outside on a very cold, snowy day?','["shorts", "sandals", "a warm coat", "a swimsuit"]'::jsonb,2,'A warm coat keeps you warm in cold weather.','original'),
('112.2.b.10.B',3,'A thermometer shows how hot or cold the air is. What does it tell about?','["rock color", "wind direction", "the Moon", "temperature"]'::jsonb,3,'A thermometer measures temperature.','original'),
('112.2.b.10.C',2,'What is wind?','["moving air", "moving water", "moving light", "moving rock"]'::jsonb,0,'Wind is air that is moving.','original'),
('112.2.b.10.C',2,'A pinwheel spins when you blow on it. What makes it spin?','["sound only", "moving air", "light", "water"]'::jsonb,1,'Moving air pushes the pinwheel.','original'),
('112.2.b.10.C',3,'A balloon gets bigger when you blow into it. What is inside?','["rocks", "light", "air", "nothing"]'::jsonb,2,'Air fills the balloon and makes it bigger.','original'),
('112.2.b.10.C',3,'Which shows that wind is blowing?','["a pencil is on the floor", "a rock sits still", "a book lies on a desk", "a flag waves"]'::jsonb,3,'A waving flag shows moving air.','original'),
('112.2.b.10.C',2,'Where is air found?','["all around us", "only on mountains", "only inside balloons", "only in clouds"]'::jsonb,0,'Air is all around us even though we cannot see it.','original'),
('112.2.b.10.C',3,'Which tool shows which way the wind blows?','["a ruler", "a windsock", "a magnet", "a scale"]'::jsonb,1,'A windsock points the way the wind is blowing.','original'),
('112.2.b.10.C',4,'A kite flies high on a day with strong wind. Why?','["the Sun pulls it", "rocks hold it up", "moving air pushes it up", "the kite makes its own light"]'::jsonb,2,'Moving air pushes against the kite and lifts it.','original'),
('112.2.b.11',2,'What do plants need from soil?','["electricity", "magnets", "sound", "nutrients and a place to grow"]'::jsonb,3,'Plants get nutrients and a place to grow from soil.','original'),
('112.2.b.11',2,'Which is a way people use water?','["drinking", "sleeping on it", "singing", "flying"]'::jsonb,0,'People drink water to stay healthy.','original'),
('112.2.b.11',3,'How can people use rocks?','["to make shadows", "to build walls and roads", "to make rain", "to make wind"]'::jsonb,1,'People use rocks to build walls, roads, and houses.','original'),
('112.2.b.11',3,'Which use of water is for staying clean?','["sorting socks", "kicking a ball", "washing hands", "flying a kite"]'::jsonb,2,'Washing hands uses water to get clean.','original'),
('112.2.b.11',2,'A farmer grows food in the ground. What material is used?','["a flag", "a magnet", "a mirror", "soil"]'::jsonb,3,'Farmers grow food in soil.','original'),
('112.2.b.11',3,'Which job needs water?','["growing a garden", "sorting rocks by color", "painting with sand only", "lighting a lamp"]'::jsonb,0,'A garden needs water to grow.','original'),
('112.2.b.11',4,'Which is a way to use sand and rocks?','["to make a cloud", "to make a path", "to make a sound", "to make a shadow"]'::jsonb,1,'People use sand and rocks to make paths and roads.','original'),
('112.2.b.12.A',1,'What do plants need to grow?','["candy and juice", "a blanket", "water and sunlight", "toys and games"]'::jsonb,2,'Plants need water, sunlight, air, nutrients, and space.','original'),
('112.2.b.12.A',2,'A plant sits in a dark closet and is never watered. What will happen?','["it will grow bigger flowers", "it will turn into an animal", "it will grow very fast", "it will not grow well"]'::jsonb,3,'Plants need light and water to grow well.','original'),
('112.2.b.12.A',3,'Where do plants get nutrients?','["from soil", "from the Moon", "from shadows", "from magnets"]'::jsonb,0,'Plant roots take in nutrients from the soil.','original'),
('112.2.b.12.A',3,'Why do many plants grow toward a window?','["they need sand", "they need sunlight", "they need sound", "they need cold"]'::jsonb,1,'Plants grow toward light because they need sunlight.','original'),
('112.2.b.12.A',2,'Seeds are planted too close together. What might the plants be missing?','["a light bulb only", "a magnet", "space to grow", "a rock"]'::jsonb,2,'Plants need space to grow.','original'),
('112.2.b.12.A',3,'Which is NOT needed for a plant to live?','["sunlight", "water", "air", "toys"]'::jsonb,3,'Plants need air, water, and sunlight, but not toys.','original'),
('112.2.b.12.A',4,'A student gives one plant water and sun and another plant only sun. Which plant will grow better?','["the plant with water and sun", "the plant with only sun", "they will grow the same", "neither will grow"]'::jsonb,0,'Plants need both water and sunlight.','original'),
('112.2.b.12.B',1,'What do animals need to live?','["books only", "air, water, and food", "TV and games", "toys and candy"]'::jsonb,1,'Animals need air, water, food, space, and shelter.','original'),
('112.2.b.12.B',2,'A bird builds a nest. What does the nest give the bird?','["air", "water", "shelter", "food"]'::jsonb,2,'A nest is a shelter for the bird.','original'),
('112.2.b.12.B',2,'A fish lives in water. What does water give the fish?','["a place to nap on a bed", "a tree", "sunlight only", "a place to live and the air it needs"]'::jsonb,3,'Fish live in water and take in air from it.','original'),
('112.2.b.12.B',3,'A rabbit eats grass. What does grass give the rabbit?','["food", "shelter only", "a shadow", "a magnet"]'::jsonb,0,'The rabbit gets food from grass.','original'),
('112.2.b.12.B',3,'A dog needs room to run and play. What is this need called?','["a color", "space", "a toy", "a shadow"]'::jsonb,1,'Animals need space to move and live.','original'),
('112.2.b.12.B',2,'A squirrel hides in a hole in a tree during a storm. What does the hole give the squirrel?','["a map", "light", "shelter", "food"]'::jsonb,2,'A hole in a tree is a shelter.','original'),
('112.2.b.12.B',4,'A pet has food, shelter, and space but no water. What will happen?','["it will be fine for a year", "it will grow wings", "it will turn into a plant", "it will not stay healthy"]'::jsonb,3,'Animals need water to live.','original'),
('112.2.b.13.A',1,'Which part of a plant grows under the ground?','["roots", "flower", "fruit", "leaf"]'::jsonb,0,'Roots grow under the ground.','original'),
('112.2.b.13.A',2,'Which plant part holds the plant up?','["seed coat", "stem", "root hair", "petal"]'::jsonb,1,'The stem holds up the plant.','original'),
('112.2.b.13.A',2,'Which plant part makes food using sunlight?','["root", "stem", "leaf", "seed"]'::jsonb,2,'Leaves use sunlight to make food for the plant.','original'),
('112.2.b.13.A',2,'Which plant part is often colorful and smells nice?','["leaf", "root", "stem", "flower"]'::jsonb,3,'Flowers are often colorful and smell nice.','original'),
('112.2.b.13.A',3,'Which plant part takes in water from the soil?','["roots", "leaves", "fruits", "flowers"]'::jsonb,0,'Roots take in water from the soil.','original'),
('112.2.b.13.A',3,'An apple is the part of an apple tree that holds the seeds. What is it called?','["leaf", "fruit", "root", "stem"]'::jsonb,1,'A fruit holds the seeds.','original'),
('112.2.b.13.A',3,'Which list names only plant parts?','["beak, wing, tail", "paw, tail, fur", "root, stem, leaf", "fin, gill, scale"]'::jsonb,2,'Roots, stems, and leaves are parts of a plant.','original'),
('112.2.b.13.B',2,'Which body part helps a person see?','["hands", "feet", "ears", "eyes"]'::jsonb,3,'Eyes are used for seeing.','original'),
('112.2.b.13.B',2,'Which body part helps an animal hear?','["ears", "paws", "nose", "tail"]'::jsonb,0,'Ears are used for hearing.','original'),
('112.2.b.13.B',2,'A bird uses its wings to do what?','["swim like a fish", "fly", "dig in soil", "climb walls"]'::jsonb,1,'Wings help birds fly.','original'),
('112.2.b.13.B',3,'A monkey uses its hands and tail to do what?','["swim underwater", "fly", "grasp branches", "dig tunnels"]'::jsonb,2,'Monkeys grasp branches with hands and tail.','original'),
('112.2.b.13.B',3,'A fish uses its fins to do what?','["run on land", "fly in the sky", "climb trees", "move in water"]'::jsonb,3,'Fins help fish move in water.','original'),
('112.2.b.13.B',3,'A dog sniffs the air. Which body part is it using?','["nose", "eyes", "paws", "tail"]'::jsonb,0,'A dog smells with its nose.','original'),
('112.2.b.13.B',4,'Which animal body part helps it grab food?','["a rabbit''s ears", "a bird''s claws", "a deer''s eyes", "a fish''s tail"]'::jsonb,1,'A bird uses its claws to grab food.','original'),
('112.2.b.13.C',2,'What comes first in a plant life cycle?','["plant", "flower", "seed", "fruit"]'::jsonb,2,'A plant life cycle starts with a seed.','original'),
('112.2.b.13.C',2,'A seed begins to grow and a tiny plant comes out. What is it called?','["flower", "root", "fruit", "seedling"]'::jsonb,3,'A tiny new plant is a seedling.','original'),
('112.2.b.13.C',3,'Which shows the plant life cycle in order?','["seed, seedling, plant, flower, fruit", "fruit, seed, flower, plant", "plant, seed, fruit, seedling", "flower, seed, fruit, plant"]'::jsonb,0,'A plant grows from seed to seedling to plant, then makes flowers and fruit.','original'),
('112.2.b.13.C',3,'What do flowers on a plant often turn into?','["soil", "fruit", "rocks", "roots"]'::jsonb,1,'Flowers can become fruit with seeds inside.','original'),
('112.2.b.13.C',3,'A seedling grows bigger. What does it become?','["an animal", "a rock", "a plant", "a seed"]'::jsonb,2,'A seedling grows into a plant.','original'),
('112.2.b.13.C',3,'What is inside many fruits?','["shadows", "rocks", "magnets", "seeds"]'::jsonb,3,'Many fruits have seeds inside.','original'),
('112.2.b.13.C',4,'A student draws four pictures of a bean plant. Which picture should come SECOND?','["a small seedling", "a plant with fruit", "a big flower", "a seed in a packet"]'::jsonb,0,'The seed comes first, then the seedling.','original'),
('112.2.b.13.D',2,'A seed is taken from a parent plant and planted. What will the seed grow into?','["a plant of a very different kind", "a young plant that looks like the parent", "an animal", "a rock"]'::jsonb,1,'Seeds grow into the same kind of plant as the parent.','original'),
('112.2.b.13.D',2,'A bean seed is planted. What will grow?','["a daisy", "an apple tree", "a bean plant", "a corn plant"]'::jsonb,2,'A bean seed grows into a bean plant.','original'),
('112.2.b.13.D',3,'A young oak tree looks most like which plant?','["a cactus", "a rosebush", "a corn plant", "a grown oak tree"]'::jsonb,3,'Young plants look like their parent plants.','original'),
('112.2.b.13.D',3,'A seedling has leaves that look like its parent''s leaves. What does this show?','["young plants look like their parents", "all plants look the same", "seedlings are rocks", "young plants have no leaves"]'::jsonb,0,'Young plants resemble their parent plants.','original'),
('112.2.b.13.D',3,'Which seed would grow into a plant with many yellow petals like its parent?','["a seed from a bean", "a seed from a sunflower", "a seed from a pine tree", "a seed from a pumpkin"]'::jsonb,1,'A sunflower seed grows into a sunflower.','original'),
('112.2.b.13.D',2,'A tomato seed is planted. What will grow?','["a cactus", "a grass plant", "a tomato plant", "a lemon tree"]'::jsonb,2,'Seeds grow into the same kind of plant.','original'),
('112.2.b.13.D',4,'A grown pine tree makes seeds. What will a pine seed grow into?','["an oak tree", "a flower", "a bush", "a pine tree"]'::jsonb,3,'A pine seed grows into a pine tree.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Science' and d.language = 'en'
on conflict (fingerprint) do nothing;
